from pathlib import Path
import json,psutil,yaml
home=Path('.local/hermes-lab/home');pid=json.loads((home/'gateway.pid').read_text())['pid'];proc=psutil.Process(pid)
processes=[proc]+proc.children(recursive=True)
print(json.dumps({'processes':[{'pid':p.pid,'name':p.name(),'rss_bytes':p.memory_info().rss} for p in processes],'combined_rss_bytes':sum(p.memory_info().rss for p in processes)},indent=2))
for p in [home/'config.yaml',home/'profiles/owner-b-real/config.yaml']:
 d=yaml.safe_load(p.read_text())
 for k,v in d.items():
  if k in ('profile_routes','profiles','routing','profile','model','gateway'):
   if k=='gateway':v={name:value for name,value in v.items() if name in ('multiplex_profiles','profile_routes','default_profile','profile_routing')}
   if k=='model':v={name:value for name,value in v.items() if name in ('provider','default','openai_runtime')}
   print(json.dumps({'config':str(p.relative_to(home)),'key':k,'value':v}))
 print(json.dumps({'config':str(p.relative_to(home)),'toolsets':d.get('platform_toolsets'),'disabled_toolsets':d.get('agent',{}).get('disabled_toolsets'),'top_level_keys':list(d)}))
PY
